describe("solana-vm withdrawal codec fixtures", () => {
  const nativeTransfer: DecodedSolanaVmWithdrawal = {
    vmType: "solana-vm",
    withdrawal: {
      domain: "0x" + "ab".repeat(32),
      recipient: "So11111111111111111111111111111111111111112",
      // System program = native SOL sentinel
      token: "11111111111111111111111111111111",
      amount: "123456789",
      nonce: "7",
      expiration: 1735680000,
      vaultAddress: "TokenkegQfeZyiNwAJbNbGKPFXCWuBvf9Ss623VQ5DA",
    },
  }

  const splTransfer: DecodedSolanaVmWithdrawal = {
    vmType: "solana-vm",
    withdrawal: {
      ...nativeTransfer.withdrawal,
      token: "EPjFWdd5AufqSSqeM2qN1xzybapC8G4wEGGkZwyTDt1v",
    },
  }

  it("native transfer pins", () => {
    expect(encodeWithdrawal(nativeTransfer)).toMatchInlineSnapshot(
      `"0xabababababababababababababababababababababababababababababababab069b8857feab8184fb687f634618c035dac439dc1aeb3b5598a0f000000000010015cd5b07000000000700000000000000006074670000000006ddf6e1d765a193d9cbe146ceeb79ac1cb485ed5f5b37913a8cf5857eff00a9"`
    )
    expect(getDecodedWithdrawalId(nativeTransfer)).toMatchInlineSnapshot(
      `"0x8a67bb2feb87ddb1a954ca9a980a0e6ead37a03874d8466162b60e2d6e9ed8f5"`
    )
    expect(getDecodedWithdrawalCurrency(nativeTransfer)).toBe(
      "11111111111111111111111111111111"
    )
    expect(getDecodedWithdrawalAmount(nativeTransfer)).toBe("123456789")
    expect(getDecodedWithdrawalRecipient(nativeTransfer)).toBe(
      "So11111111111111111111111111111111111111112"
    )
    expect(
      decodeWithdrawal(encodeWithdrawal(nativeTransfer), "solana-vm")
    ).toEqual(nativeTransfer)
  })

  it("spl token transfer pins", () => {
    expect(encodeWithdrawal(splTransfer)).toMatchInlineSnapshot(
      `""`
    )
    expect(getDecodedWithdrawalId(splTransfer)).toMatchInlineSnapshot(
      `"0x9eebe02238d0db346443a0278d91cb1e62d80cce625c41253d1a59f44fdb1b3d"`
    )
    expect(getDecodedWithdrawalCurrency(splTransfer)).toBe(
      "EPjFWdd5AufqSSqeM2qN1xzybapC8G4wEGGkZwyTDt1v"
    )
    expect(
      decodeWithdrawal(encodeWithdrawal(splTransfer), "solana-vm")
    ).toEqual(splTransfer)
  })
})

describe("bitcoin-vm withdrawal codec fixtures", () => {
  // encode/decode are hex passthrough and getId hashes the 0x-prefixed string,
  // so the fixture doesn't need to be a parseable PSBT. getAmount/getRecipient
  // DO finalize a real PSBT and are not pinned here (no signed PSBT fixture
  // available) — they remain covered only by downstream usage.
  const withdrawal: DecodedBitcoinVmWithdrawal = {
    vmType: "bitcoin-vm",
    withdrawal: {
      psbt: "70736274ff0100520200000001aabbccdd",
    },
  }

  it("passthrough + id pins", () => {
    expect(encodeWithdrawal(withdrawal)).toBe(
      "0x70736274ff0100520200000001aabbccdd"
    )
    expect(getDecodedWithdrawalId(withdrawal)).toMatchInlineSnapshot(
      `"0x2afe732745aaa8d89797e381b272726ba93de0e3e9d2fc248fc0b92db7da2eef"`
    )
    expect(getDecodedWithdrawalCurrency(withdrawal)).toMatchInlineSnapshot(
      `"bc1qqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqmql8k8"`
    )
    expect(
      decodeWithdrawal(encodeWithdrawal(withdrawal), "bitcoin-vm")
    ).toEqual(withdrawal)
  })
})

